import json
import time
import random
import traceback
import threading
from dataclasses import dataclass, field
from typing import Any, Callable, TypeVar

LOG_LOCK = threading.Lock()
DEFAULT_RETRY_BASE_MS = 150
DEFAULT_RETRY_MAX_MS = 2500
DEFAULT_MAX_RETRIES = 4
BACKOFF_JITTER_MS = 50
TRACEBACK_LIMIT = 8

T = TypeVar('T')


def log(level: str, msg: str, **fields: Any) -> None:
    if not isinstance(level, str) or not level:
        level = "info"
    if not isinstance(msg, str) or not msg:
        msg = "unknown"

    try:
        ts = int(time.time() * 1000)
    except Exception:
        ts = 0

    sanitized_fields = {}
    for k, v in fields.items():
        if not isinstance(k, str):
            continue
        try:
            json.dumps(v)
            sanitized_fields[k] = v
        except (TypeError, ValueError):
            sanitized_fields[k] = str(v)

    rec = {"ts": ts, "level": level, "msg": msg, **sanitized_fields}

    with LOG_LOCK:
        try:
            print(json.dumps(rec, ensure_ascii=True), flush=True)
        except Exception:
            pass


@dataclass(frozen=True)
class RetryPolicy:
    max_retries: int = field(default=DEFAULT_MAX_RETRIES)
    base_ms: int = field(default=DEFAULT_RETRY_BASE_MS)
    max_ms: int = field(default=DEFAULT_RETRY_MAX_MS)

    def __post_init__(self) -> None:
        if self.max_retries < 0:
            object.__setattr__(self, 'max_retries', 0)
        if self.base_ms < 0:
            object.__setattr__(self, 'base_ms', 1)
        if self.max_ms < self.base_ms:
            object.__setattr__(self, 'max_ms', self.base_ms)


def with_retry(
    fn: Callable[[], T],
    policy: RetryPolicy,
    op: str,
    classify: Callable[[Exception], bool]
) -> T:
    if not callable(fn):
        raise TypeError("fn must be callable")
    if not callable(classify):
        raise TypeError("classify must be callable")
    if not isinstance(op, str):
        op = "unknown_op"

    attempt = 0
    last_exception: Exception | None = None

    while attempt <= policy.max_retries:
        try:
            result = fn()
            if attempt > 0:
                log("info", "op_success_after_retry", op=op, attempt=attempt)
            return result
        except Exception as e:
            last_exception = e
            try:
                retriable = classify(e)
            except Exception:
                retriable = False

            if attempt >= policy.max_retries or not retriable:
                log(
                    "error",
                    "op_failed",
                    op=op,
                    attempt=attempt,
                    err=str(e),
                    err_type=type(e).__name__,
                    tb=traceback.format_exc(limit=TRACEBACK_LIMIT)
                )
                raise

            jitter = random.randint(0, BACKOFF_JITTER_MS)
            backoff = min(policy.max_ms, policy.base_ms * (2 ** attempt)) + jitter

            log(
                "warn",
                "op_retry",
                op=op,
                attempt=attempt,
                err=str(e),
                err_type=type(e).__name__,
                backoff_ms=backoff
            )

            try:
                time.sleep(backoff / 1000.0)
            except Exception:
                pass

            attempt += 1

    if last_exception:
        raise last_exception
    raise RuntimeError(f"retry exhausted for {op}")
