import os
import json
import subprocess
import threading
from typing import Any, Dict, List

from modal_functions.common import log, with_retry, RetryPolicy

BEND_BIN_DIR_KEY = "BEND_BIN_DIR"
DEFAULT_BEND_BIN_DIR = "build/bend"
PAGERANK_BINARY = "pagerank"
SUBPROCESS_TIMEOUT_SECONDS = 120
STDERR_MAX_LENGTH = 2000
MODAL_MAX_RETRIES_KEY = "MODAL_MAX_RETRIES"
DEFAULT_MODAL_MAX_RETRIES = 4

HANDLE_GRAPH_LOCK = threading.Lock()


def _get_bend_bin_dir() -> str:
    bend_dir = os.getenv(BEND_BIN_DIR_KEY, DEFAULT_BEND_BIN_DIR)
    if not isinstance(bend_dir, str) or not bend_dir:
        return DEFAULT_BEND_BIN_DIR
    return os.path.abspath(bend_dir)


def _get_max_retries() -> int:
    retries_str = os.getenv(MODAL_MAX_RETRIES_KEY, str(DEFAULT_MODAL_MAX_RETRIES))
    try:
        retries = int(retries_str)
        return max(0, retries)
    except (ValueError, TypeError):
        return DEFAULT_MODAL_MAX_RETRIES


def handle_graph(req: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(req, dict):
        return {"error": "invalid_request_type"}

    nodes = req.get("nodes")

    if isinstance(nodes, str):
        try:
            nodes = json.loads(nodes)
        except Exception as e:
            log("error", "graph_nodes_parse_failed", err=str(e))
            return {"error": "invalid_nodes_json"}

    if not isinstance(nodes, list):
        return {"error": "nodes_must_be_list"}

    if len(nodes) == 0:
        return {"error": "nodes_list_empty"}

    for idx, node in enumerate(nodes):
        if not isinstance(node, (str, int, float, dict)):
            return {"error": f"invalid_node_type_at_index_{idx}"}

    bend_dir = _get_bend_bin_dir()
    pagerank_bin = os.path.join(bend_dir, PAGERANK_BINARY)

    if not os.path.exists(pagerank_bin):
        log("error", "pagerank_binary_missing", path=pagerank_bin)
        return {"error": "pagerank_binary_not_found", "path": pagerank_bin}

    if not os.access(pagerank_bin, os.X_OK):
        log("error", "pagerank_binary_not_executable", path=pagerank_bin)
        return {"error": "pagerank_binary_not_executable"}

    inp = json.dumps({"nodes": nodes}, ensure_ascii=True)
    policy = RetryPolicy(max_retries=_get_max_retries())

    def run() -> Dict[str, Any]:
        with HANDLE_GRAPH_LOCK:
            try:
                p = subprocess.run(
                    [pagerank_bin, "--json"],
                    input=inp.encode("utf-8"),
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    timeout=SUBPROCESS_TIMEOUT_SECONDS,
                    check=False
                )
            except subprocess.TimeoutExpired as e:
                log("error", "pagerank_timeout", err=str(e))
                raise RuntimeError("pagerank_execution_timeout")
            except Exception as e:
                log("error", "pagerank_execution_failed", err=str(e))
                raise

            if p.returncode != 0:
                stderr_msg = p.stderr.decode("utf-8", errors="replace")[:STDERR_MAX_LENGTH]
                log("error", "pagerank_nonzero_exit", code=p.returncode, stderr=stderr_msg)
                raise RuntimeError(f"pagerank_failed_code_{p.returncode}")

            try:
                result = json.loads(p.stdout.decode("utf-8"))
                if not isinstance(result, dict):
                    raise ValueError("result_not_dict")
                return result
            except Exception as e:
                log("error", "pagerank_output_parse_failed", err=str(e))
                raise RuntimeError("pagerank_invalid_output")

    return with_retry(run, policy, "graph_compute", classify=lambda e: True)


try:
    import modal

    app = modal.App("neural-search-graph-compute")

    image = (
        modal.Image.debian_slim(python_version="3.11")
        .apt_install("build-essential")
    )

    vol = modal.Volume.from_name("neural-search-graph", create_if_missing=True)

    @app.function(
        image=image,
        cpu=4.0,
        memory=8192,
        volumes={"/graph": vol},
        timeout=600
    )
    def graph(nodes: List[str]) -> Dict[str, Any]:
        if not isinstance(nodes, list):
            return {"error": "nodes_must_be_list"}
        os.environ[BEND_BIN_DIR_KEY] = "/graph"
        return handle_graph({"nodes": nodes})

except ImportError:
    log("warn", "modal_import_failed", component="graph_compute")
    app = None
except Exception as e:
    log("error", "modal_init_failed", component="graph_compute", err=str(e))
    app = None
