import json
import argparse
import signal
import sys
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer, ThreadingHTTPServer
from typing import Any, Dict

from modal_functions.common import log
from modal_functions.embedding_encode import handle_encode
from modal_functions.vector_search import handle_search
from modal_functions.graph_compute import handle_graph
from modal_functions.batch_indexer import index_documents

SERVER_VERSION = "NeuralSearchModalDev/1.0.0"
DEFAULT_HOST = "127.0.0.1"
DEFAULT_PORT = 9001
MAX_CONTENT_LENGTH = 100 * 1024 * 1024
MIN_PORT = 1
MAX_PORT = 65535

shutdown_event = threading.Event()


class Handler(BaseHTTPRequestHandler):
    server_version = SERVER_VERSION

    def log_message(self, format: str, *args: Any) -> None:
        log("info", "http_access", method=self.command, path=self.path, client=self.client_address[0])

    def _read_json(self) -> Dict[str, Any]:
        content_length_str = self.headers.get("Content-Length", "0")
        try:
            n = int(content_length_str)
        except (ValueError, TypeError):
            log("warn", "invalid_content_length", value=content_length_str)
            return {}

        if n < 0:
            log("warn", "negative_content_length", value=n)
            return {}

        if n > MAX_CONTENT_LENGTH:
            log("error", "content_length_too_large", value=n, max=MAX_CONTENT_LENGTH)
            self._send(413, {"error": "request_entity_too_large"})
            return {}

        if n == 0:
            return {}

        try:
            raw = self.rfile.read(n)
            if len(raw) != n:
                log("warn", "incomplete_read", expected=n, actual=len(raw))
            decoded = raw.decode("utf-8")
            return json.loads(decoded) if decoded else {}
        except UnicodeDecodeError as e:
            log("error", "request_decode_failed", err=str(e))
            return {}
        except json.JSONDecodeError as e:
            log("error", "request_json_invalid", err=str(e))
            return {}
        except Exception as e:
            log("error", "request_read_failed", err=str(e))
            return {}

    def _send(self, code: int, obj: Dict[str, Any]) -> None:
        if not isinstance(code, int) or code < 100 or code > 599:
            code = 500

        if not isinstance(obj, dict):
            obj = {"error": "internal_error"}

        try:
            body = json.dumps(obj, ensure_ascii=True).encode("utf-8")
        except Exception as e:
            log("error", "response_serialize_failed", err=str(e))
            body = json.dumps({"error": "serialization_failed"}, ensure_ascii=True).encode("utf-8")

        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("X-Frame-Options", "DENY")
            self.end_headers()
            self.wfile.write(body)
        except Exception as e:
            log("error", "response_send_failed", err=str(e))

    def do_POST(self) -> None:
        content_type = self.headers.get("Content-Type", "")
        if "application/json" not in content_type and content_type != "":
            log("warn", "unexpected_content_type", value=content_type)

        req = self._read_json()

        if not isinstance(req, dict):
            self._send(400, {"error": "invalid_request"})
            return

        log("info", "request_received", path=self.path, size=len(json.dumps(req)))

        try:
            path = self.path.split('?')[0]

            if path == "/encode":
                out = handle_encode(req)
                self._send(200, out)
                return

            if path == "/search":
                out = handle_search(req)
                self._send(200, out)
                return

            if path == "/graph":
                out = handle_graph(req)
                self._send(200, out)
                return

            if path == "/index":
                docs = req.get("docs", [])
                if not isinstance(docs, list):
                    self._send(400, {"error": "docs_must_be_list"})
                    return
                out = index_documents(docs)
                self._send(200, out)
                return

            if path == "/health":
                self._send(200, {"status": "healthy"})
                return

            self._send(404, {"error": "endpoint_not_found", "path": path})

        except Exception as e:
            log("error", "request_handler_exception", path=self.path, err=str(e), err_type=type(e).__name__)
            self._send(500, {"error": "internal_server_error"})


def signal_handler(signum: int, frame: Any) -> None:
    log("info", "shutdown_signal_received", signal=signum)
    shutdown_event.set()


def main() -> None:
    ap = argparse.ArgumentParser(description="Neural Search Modal Development Server")
    ap.add_argument("--host", default=DEFAULT_HOST, help=f"Host to bind (default: {DEFAULT_HOST})")
    ap.add_argument("--port", type=int, default=DEFAULT_PORT, help=f"Port to bind (default: {DEFAULT_PORT})")
    args = ap.parse_args()

    if not isinstance(args.port, int) or args.port < MIN_PORT or args.port > MAX_PORT:
        log("error", "invalid_port", port=args.port)
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    except Exception as e:
        log("error", "server_creation_failed", host=args.host, port=args.port, err=str(e))
        sys.exit(1)

    log("info", "server_listening", host=args.host, port=args.port)

    try:
        while not shutdown_event.is_set():
            httpd.handle_request()
    except KeyboardInterrupt:
        log("info", "keyboard_interrupt")
    except Exception as e:
        log("error", "server_error", err=str(e))
    finally:
        httpd.shutdown()
        httpd.server_close()
        log("info", "server_stopped")


if __name__ == "__main__":
    main()
