import os
import json
import threading
from typing import Any, Dict, List

from modal_functions.common import log, with_retry, RetryPolicy

try:
    import torch
    from transformers import AutoTokenizer, AutoModel
    TORCH_AVAILABLE = True
except ImportError as import_error:
    log("error", "transformers_import_failed", err=str(import_error))
    torch = None
    AutoTokenizer = None
    AutoModel = None
    TORCH_AVAILABLE = False

MODEL_NAME_KEY = "EMBED_MODEL"
DEFAULT_MODEL_NAME = "intfloat/e5-large-v2"
EMBEDDING_DIMENSION = 1024
MAX_TOKEN_LENGTH = 512
NORMALIZATION_EPSILON = 1e-9
MODAL_MAX_RETRIES_KEY = "MODAL_MAX_RETRIES"
DEFAULT_MODAL_MAX_RETRIES = 4

_encoder_lock = threading.Lock()
_encoder_instance = None


def _get_model_name() -> str:
    model_name = os.getenv(MODEL_NAME_KEY, DEFAULT_MODEL_NAME)
    if not isinstance(model_name, str) or not model_name:
        return DEFAULT_MODEL_NAME
    return model_name


def _get_max_retries() -> int:
    retries_str = os.getenv(MODAL_MAX_RETRIES_KEY, str(DEFAULT_MODAL_MAX_RETRIES))
    try:
        retries = int(retries_str)
        return max(0, retries)
    except (ValueError, TypeError):
        return DEFAULT_MODAL_MAX_RETRIES


class Encoder:
    def __init__(self) -> None:
        if not TORCH_AVAILABLE or torch is None:
            raise RuntimeError("torch_and_transformers_not_available")

        model_name = _get_model_name()

        try:
            log("info", "tokenizer_loading", model=model_name)
            self.tokenizer = AutoTokenizer.from_pretrained(model_name)
            log("info", "tokenizer_loaded", model=model_name)
        except Exception as e:
            log("error", "tokenizer_load_failed", model=model_name, err=str(e))
            raise

        try:
            log("info", "model_loading", model=model_name)
            self.model = AutoModel.from_pretrained(model_name)
            self.model.eval()
            log("info", "model_loaded", model=model_name)
        except Exception as e:
            log("error", "model_load_failed", model=model_name, err=str(e))
            raise

        self.device = "cpu"
        if torch.cuda.is_available():
            try:
                self.model = self.model.cuda()
                self.device = "cuda"
                log("info", "model_moved_to_cuda")
            except Exception as e:
                log("warn", "cuda_move_failed", err=str(e))
                self.device = "cpu"

    def encode(self, text: str) -> List[float]:
        if not isinstance(text, str):
            raise ValueError("text_must_be_string")

        if not text.strip():
            raise ValueError("text_cannot_be_empty")

        try:
            tok = self.tokenizer(
                text,
                max_length=MAX_TOKEN_LENGTH,
                truncation=True,
                padding=True,
                return_tensors="pt"
            )
        except Exception as e:
            log("error", "tokenization_failed", err=str(e))
            raise RuntimeError("tokenization_error")

        if "input_ids" not in tok or "attention_mask" not in tok:
            raise RuntimeError("tokenizer_missing_required_keys")

        try:
            tok = {k: v.to(self.device) for k, v in tok.items()}
        except Exception as e:
            log("error", "tensor_device_move_failed", err=str(e))
            raise RuntimeError("tensor_move_error")

        try:
            with torch.no_grad():
                out = self.model(**tok)
        except Exception as e:
            log("error", "model_forward_failed", err=str(e))
            raise RuntimeError("model_inference_error")

        if not hasattr(out, "last_hidden_state"):
            raise RuntimeError("model_output_missing_last_hidden_state")

        last = out.last_hidden_state
        mask = tok["attention_mask"].unsqueeze(-1)

        pooled = (last * mask).sum(dim=1) / mask.sum(dim=1).clamp(min=1.0)

        norm = torch.linalg.norm(pooled, dim=1, keepdim=True)
        pooled = pooled / (norm + NORMALIZATION_EPSILON)

        if pooled.shape[0] < 1:
            raise RuntimeError("pooled_tensor_empty")

        vec = pooled[0].detach().cpu().float().numpy()

        if vec.shape[0] != EMBEDDING_DIMENSION:
            raise RuntimeError(f"embedding_dimension_mismatch_expected_{EMBEDDING_DIMENSION}_got_{vec.shape[0]}")

        return vec.tolist()


def get_encoder() -> Encoder:
    global _encoder_instance

    with _encoder_lock:
        if _encoder_instance is None:
            log("info", "encoder_initializing", model=_get_model_name())
            try:
                _encoder_instance = Encoder()
                log("info", "encoder_initialized")
            except Exception as e:
                log("error", "encoder_init_failed", err=str(e))
                raise
        return _encoder_instance


def handle_encode(req: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(req, dict):
        return {"error": "invalid_request_type"}

    text = req.get("text", "")

    if not isinstance(text, str):
        return {"error": "text_must_be_string"}

    if not text.strip():
        return {"error": "text_cannot_be_empty"}

    policy = RetryPolicy(max_retries=_get_max_retries())

    def run() -> Dict[str, Any]:
        try:
            enc = get_encoder()
            emb = enc.encode(text)
            return {"embedding": emb}
        except Exception as e:
            log("error", "encode_execution_failed", err=str(e), err_type=type(e).__name__)
            raise

    try:
        return with_retry(run, policy, "encode", classify=lambda e: isinstance(e, (RuntimeError, IOError)))
    except Exception as e:
        log("error", "encode_failed_after_retries", err=str(e))
        return {"error": "encoding_failed", "detail": str(e)}


try:
    import modal

    app = modal.App("neural-search-embedding-encode")

    image = (
        modal.Image.debian_slim(python_version="3.11")
        .pip_install(
            "torch==2.1.0",
            "transformers==4.35.0",
            "numpy==1.24.3"
        )
    )

    @app.function(
        image=image,
        gpu="T4",
        memory=16384,
        timeout=600
    )
    def encode(text: str) -> Dict[str, Any]:
        if not isinstance(text, str):
            return {"error": "text_must_be_string"}
        return handle_encode({"text": text})

except ImportError:
    log("warn", "modal_import_failed", component="embedding_encode")
    app = None
except Exception as e:
    log("error", "modal_init_failed", component="embedding_encode", err=str(e))
    app = None
