import os
import json
import threading
from typing import Any, Dict, List, Tuple

import numpy as np

from modal_functions.common import log, with_retry, RetryPolicy

INDEX_DIR_KEY = "INDEX_DIR"
DEFAULT_INDEX_DIR = "/var/lib/neural-search/index"
VECTORS_FILENAME = "vectors.npy"
METADATA_FILENAME = "meta.jsonl"
EMBEDDING_DIMENSION = 1024
DEFAULT_TOP_K = 10
MAX_TOP_K = 1000
NORMALIZATION_EPSILON = 1e-9

_index_lock = threading.Lock()
_vecs_cache = None
_meta_cache = None


def _get_index_dir() -> str:
    index_dir = os.getenv(INDEX_DIR_KEY, DEFAULT_INDEX_DIR)
    if not isinstance(index_dir, str) or not index_dir:
        return DEFAULT_INDEX_DIR
    return os.path.abspath(index_dir)


def _get_vec_path() -> str:
    return os.path.join(_get_index_dir(), VECTORS_FILENAME)


def _get_meta_path() -> str:
    return os.path.join(_get_index_dir(), METADATA_FILENAME)


def _load_index() -> Tuple[np.ndarray, List[Dict[str, Any]]]:
    vec_path = _get_vec_path()
    meta_path = _get_meta_path()

    if not os.path.exists(vec_path) or not os.path.exists(meta_path):
        log("info", "index_files_not_found", vec_path=vec_path, meta_path=meta_path)
        return np.zeros((0, EMBEDDING_DIMENSION), dtype=np.float32), []

    if not os.access(vec_path, os.R_OK):
        raise RuntimeError(f"vector_file_not_readable_{vec_path}")

    if not os.access(meta_path, os.R_OK):
        raise RuntimeError(f"metadata_file_not_readable_{meta_path}")

    try:
        vecs = np.load(vec_path)
        if vecs.dtype != np.float32:
            vecs = vecs.astype(np.float32)
    except Exception as e:
        log("error", "vector_load_failed", path=vec_path, err=str(e))
        raise RuntimeError(f"vector_file_corrupted_{vec_path}")

    if len(vecs.shape) != 2 or vecs.shape[1] != EMBEDDING_DIMENSION:
        raise RuntimeError(f"vector_shape_invalid_expected_(N,{EMBEDDING_DIMENSION})_got_{vecs.shape}")

    meta: List[Dict[str, Any]] = []

    try:
        with open(meta_path, "r", encoding="utf-8") as f:
            for line_num, line in enumerate(f, 1):
                line = line.strip()
                if not line:
                    continue
                try:
                    item = json.loads(line)
                    if not isinstance(item, dict):
                        log("warn", "metadata_line_not_dict", line_num=line_num)
                        continue
                    meta.append(item)
                except json.JSONDecodeError as e:
                    log("warn", "metadata_line_invalid_json", line_num=line_num, err=str(e))
                    continue
    except Exception as e:
        log("error", "metadata_load_failed", path=meta_path, err=str(e))
        raise RuntimeError(f"metadata_file_read_error_{meta_path}")

    if vecs.shape[0] != len(meta):
        raise RuntimeError(f"index_size_mismatch_vectors_{vecs.shape[0]}_metadata_{len(meta)}")

    return vecs, meta


def _ensure_loaded() -> Tuple[np.ndarray, List[Dict[str, Any]]]:
    global _vecs_cache, _meta_cache

    with _index_lock:
        if _vecs_cache is None or _meta_cache is None:
            log("info", "loading_index", path=_get_index_dir())
            try:
                _vecs_cache, _meta_cache = _load_index()
                log("info", "index_loaded", vectors=_vecs_cache.shape[0], metadata=len(_meta_cache))
            except Exception as e:
                log("error", "index_load_failed", err=str(e))
                raise
        return _vecs_cache, _meta_cache


def _topk(scores: np.ndarray, k: int) -> np.ndarray:
    if not isinstance(scores, np.ndarray):
        raise TypeError("scores_must_be_ndarray")

    if scores.ndim != 1:
        raise ValueError("scores_must_be_1d")

    n = scores.shape[0]
    k = max(0, min(k, n))

    if k == 0:
        return np.zeros((0,), dtype=np.int64)

    if k == 1:
        return np.array([np.argmax(scores)], dtype=np.int64)

    if k >= n:
        return np.argsort(scores)[::-1]

    idx = np.argpartition(scores, -k)[-k:]
    return idx[np.argsort(scores[idx])[::-1]]


def handle_search(req: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(req, dict):
        return {"error": "invalid_request_type"}

    emb = req.get("embedding")
    k_raw = req.get("k", DEFAULT_TOP_K)

    if isinstance(emb, str):
        try:
            emb = json.loads(emb)
        except Exception as e:
            log("error", "embedding_parse_failed", err=str(e))
            return {"error": "embedding_json_invalid"}

    if not isinstance(emb, list):
        return {"error": "embedding_must_be_list"}

    if len(emb) != EMBEDDING_DIMENSION:
        return {"error": f"embedding_dimension_invalid_expected_{EMBEDDING_DIMENSION}_got_{len(emb)}"}

    try:
        for i, val in enumerate(emb):
            if not isinstance(val, (int, float)):
                return {"error": f"embedding_element_{i}_invalid_type"}
    except Exception:
        return {"error": "embedding_validation_failed"}

    try:
        k = int(k_raw)
        if k < 1:
            k = DEFAULT_TOP_K
        if k > MAX_TOP_K:
            k = MAX_TOP_K
    except (ValueError, TypeError):
        k = DEFAULT_TOP_K

    try:
        q = np.asarray(emb, dtype=np.float32)
    except Exception as e:
        log("error", "embedding_array_conversion_failed", err=str(e))
        return {"error": "embedding_conversion_failed"}

    q_norm = np.linalg.norm(q)
    if q_norm < NORMALIZATION_EPSILON:
        return {"error": "embedding_zero_vector"}

    q = q / q_norm

    try:
        vecs, meta = _ensure_loaded()
    except Exception as e:
        log("error", "index_ensure_loaded_failed", err=str(e))
        return {"error": "index_load_error"}

    if vecs.shape[0] == 0:
        log("info", "search_on_empty_index")
        return {"results": []}

    try:
        scores = vecs @ q
    except Exception as e:
        log("error", "cosine_similarity_failed", err=str(e))
        return {"error": "search_computation_failed"}

    try:
        idx = _topk(scores, k)
    except Exception as e:
        log("error", "topk_selection_failed", err=str(e))
        return {"error": "result_ranking_failed"}

    out: List[Dict[str, Any]] = []

    for j in idx:
        j_int = int(j)
        if j_int < 0 or j_int >= len(meta):
            log("warn", "index_out_of_bounds", index=j_int, meta_len=len(meta))
            continue

        m = meta[j_int]

        if not isinstance(m, dict):
            log("warn", "metadata_not_dict", index=j_int)
            continue

        doc_id = m.get("id", j_int)
        try:
            doc_id = int(doc_id)
        except (ValueError, TypeError):
            doc_id = j_int

        title = m.get("title", "")
        if not isinstance(title, str):
            title = str(title)

        url = m.get("url", "")
        if not isinstance(url, str):
            url = str(url)

        text = m.get("text", "")
        if not isinstance(text, str):
            text = str(text)

        score = float(scores[j_int])

        out.append({
            "id": doc_id,
            "score": score,
            "title": title,
            "url": url,
            "text": text,
        })

    return {"results": out, "total": len(out)}


