import os
import json
import tempfile
import shutil
import threading
from typing import Any, Dict, List, Tuple

import numpy as np

from modal_functions.common import log, with_retry, RetryPolicy
from modal_functions.embedding_encode import handle_encode

INDEX_DIR_KEY = "INDEX_DIR"
DEFAULT_INDEX_DIR = "/var/lib/neural-search/index"
VECTORS_FILENAME = "vectors.npy"
METADATA_FILENAME = "meta.jsonl"
EMBEDDING_DIMENSION = 1024
MAX_TEXT_LENGTH = 8000
MAX_TITLE_LENGTH = 500
MAX_URL_LENGTH = 2000
MODAL_MAX_RETRIES_KEY = "MODAL_MAX_RETRIES"
DEFAULT_MODAL_MAX_RETRIES = 4
DOC_SOURCE_JSON_KEY = "DOC_SOURCE_JSON"
NORMALIZATION_EPSILON = 1e-9

_index_lock = threading.Lock()


def _get_index_dir() -> str:
    index_dir = os.getenv(INDEX_DIR_KEY, DEFAULT_INDEX_DIR)
    if not isinstance(index_dir, str) or not index_dir:
        return DEFAULT_INDEX_DIR
    return os.path.abspath(index_dir)


def _get_vec_path() -> str:
    return os.path.join(_get_index_dir(), VECTORS_FILENAME)


def _get_meta_path() -> str:
    return os.path.join(_get_index_dir(), METADATA_FILENAME)


def _get_max_retries() -> int:
    retries_str = os.getenv(MODAL_MAX_RETRIES_KEY, str(DEFAULT_MODAL_MAX_RETRIES))
    try:
        retries = int(retries_str)
        return max(0, retries)
    except (ValueError, TypeError):
        return DEFAULT_MODAL_MAX_RETRIES


def _ensure_dir() -> None:
    index_dir = _get_index_dir()
    try:
        os.makedirs(index_dir, mode=0o755, exist_ok=True)
        if not os.access(index_dir, os.W_OK):
            raise RuntimeError(f"index_dir_not_writable_{index_dir}")
    except Exception as e:
        log("error", "ensure_dir_failed", path=index_dir, err=str(e))
        raise


def _load() -> Tuple[np.ndarray, List[Dict[str, Any]]]:
    vec_path = _get_vec_path()
    meta_path = _get_meta_path()

    if not os.path.exists(vec_path) or not os.path.exists(meta_path):
        log("info", "index_files_not_found_returning_empty")
        return np.zeros((0, EMBEDDING_DIMENSION), dtype=np.float32), []

    try:
        vecs = np.load(vec_path)
        if vecs.dtype != np.float32:
            vecs = vecs.astype(np.float32)
    except Exception as e:
        log("error", "vector_load_failed", path=vec_path, err=str(e))
        raise RuntimeError(f"vector_load_error_{vec_path}")

    meta: List[Dict[str, Any]] = []

    try:
        with open(meta_path, "r", encoding="utf-8") as f:
            for line_num, line in enumerate(f, 1):
                line = line.strip()
                if not line:
                    continue
                try:
                    item = json.loads(line)
                    if isinstance(item, dict):
                        meta.append(item)
                except json.JSONDecodeError as e:
                    log("warn", "metadata_line_invalid", line_num=line_num, err=str(e))
                    continue
    except Exception as e:
        log("error", "metadata_load_failed", path=meta_path, err=str(e))
        raise RuntimeError(f"metadata_load_error_{meta_path}")

    if vecs.shape[0] != len(meta):
        log("warn", "index_size_mismatch", vectors=vecs.shape[0], metadata=len(meta))

    return vecs, meta


def _save(vecs: np.ndarray, meta: List[Dict[str, Any]]) -> None:
    _ensure_dir()

    if vecs.shape[0] != len(meta):
        raise ValueError(f"vector_meta_mismatch_{vecs.shape[0]}_vs_{len(meta)}")

    vec_path = _get_vec_path()
    meta_path = _get_meta_path()

    try:
        with tempfile.NamedTemporaryFile(mode='wb', delete=False, dir=_get_index_dir()) as tmp_vec:
            tmp_vec_path = tmp_vec.name
            np.save(tmp_vec, vecs.astype(np.float32))

        os.chmod(tmp_vec_path, 0o644)
        shutil.move(tmp_vec_path, vec_path)

    except Exception as e:
        log("error", "vector_save_failed", path=vec_path, err=str(e))
        if os.path.exists(tmp_vec_path):
            try:
                os.remove(tmp_vec_path)
            except Exception:
                pass
        raise RuntimeError(f"vector_save_error_{vec_path}")

    try:
        with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', delete=False, dir=_get_index_dir()) as tmp_meta:
            tmp_meta_path = tmp_meta.name
            for m in meta:
                tmp_meta.write(json.dumps(m, ensure_ascii=True) + "\n")

        os.chmod(tmp_meta_path, 0o644)
        shutil.move(tmp_meta_path, meta_path)

    except Exception as e:
        log("error", "metadata_save_failed", path=meta_path, err=str(e))
        if os.path.exists(tmp_meta_path):
            try:
                os.remove(tmp_meta_path)
            except Exception:
                pass
        raise RuntimeError(f"metadata_save_error_{meta_path}")

    log("info", "index_saved", vectors=vecs.shape[0], metadata=len(meta))


def index_documents(docs: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not isinstance(docs, list):
        return {"error": "docs_must_be_list"}

    if len(docs) == 0:
        log("info", "index_documents_empty_input")
        return {"indexed": 0, "total": 0}

    policy = RetryPolicy(max_retries=_get_max_retries())

    def run() -> Dict[str, Any]:
        with _index_lock:
            try:
                vecs, meta = _load()
            except Exception as e:
                log("error", "load_failed_in_index", err=str(e))
                raise

            existing = set()
            for m in meta:
                if isinstance(m, dict) and "id" in m:
                    try:
                        existing.add(int(m["id"]))
                    except (ValueError, TypeError):
                        pass

            new_vecs: List[np.ndarray] = []
            new_meta: List[Dict[str, Any]] = []

            for doc_idx, d in enumerate(docs):
                if not isinstance(d, dict):
                    log("warn", "document_not_dict", index=doc_idx)
                    continue

                if "id" not in d:
                    log("warn", "document_missing_id", index=doc_idx)
                    continue

                try:
                    doc_id = int(d["id"])
                except (ValueError, TypeError) as e:
                    log("warn", "document_id_invalid", index=doc_idx, id=d.get("id"), err=str(e))
                    continue

                if doc_id in existing:
                    log("info", "document_already_indexed", id=doc_id)
                    continue

                text_raw = d.get("text", "")
                if not isinstance(text_raw, str):
                    text_raw = str(text_raw)
                text = text_raw[:MAX_TEXT_LENGTH]

                if not text.strip():
                    log("warn", "document_empty_text", id=doc_id)
                    continue

                title_raw = d.get("title", "")
                if not isinstance(title_raw, str):
                    title_raw = str(title_raw)
                title = title_raw[:MAX_TITLE_LENGTH]

                url_raw = d.get("url", "")
                if not isinstance(url_raw, str):
                    url_raw = str(url_raw)
                url = url_raw[:MAX_URL_LENGTH]

                try:
                    emb_result = handle_encode({"text": text})
                except Exception as e:
                    log("error", "encode_failed_for_document", id=doc_id, err=str(e))
                    continue

                if "error" in emb_result:
                    log("error", "encode_returned_error", id=doc_id, error=emb_result["error"])
                    continue

                emb = emb_result.get("embedding")

                if not isinstance(emb, list) or len(emb) != EMBEDDING_DIMENSION:
                    log("error", "embedding_invalid_dimension", id=doc_id, dim=len(emb) if isinstance(emb, list) else None)
                    continue

                try:
                    v = np.asarray(emb, dtype=np.float32)
                except Exception as e:
                    log("error", "embedding_array_conversion_failed", id=doc_id, err=str(e))
                    continue

                new_vecs.append(v)
                new_meta.append({
                    "id": doc_id,
                    "title": title,
                    "url": url,
                    "text": text
                })
                existing.add(doc_id)

            if len(new_vecs) == 0:
                log("info", "no_new_documents_to_index")
                return {"indexed": 0, "total": len(meta)}

            try:
                mat = np.vstack(new_vecs).astype(np.float32)
            except Exception as e:
                log("error", "vstack_failed", err=str(e))
                raise RuntimeError("vector_stacking_failed")

            norms = np.linalg.norm(mat, axis=1, keepdims=True)
            mat = mat / (norms + NORMALIZATION_EPSILON)

            if vecs.shape[0] > 0:
                vecs = np.vstack([vecs, mat])
            else:
                vecs = mat

            meta.extend(new_meta)

            try:
                _save(vecs, meta)
            except Exception as e:
                log("error", "save_failed_in_index", err=str(e))
                raise

            return {"indexed": len(new_meta), "total": len(meta)}

    try:
        return with_retry(run, policy, "batch_index", classify=lambda e: isinstance(e, (IOError, OSError, RuntimeError)))
    except Exception as e:
        log("error", "index_documents_failed_after_retries", err=str(e))
        return {"error": "indexing_failed", "detail": str(e)}


